
(function () {
'use strict';

/* 智能家庭屏壁纸：仅本页设置，terminal-3d.js 检测到才贴图 */
window.S6_SCREEN_WALLPAPER = "data:image/webp;base64,";

var DEPS = [
'assets/vendor/draco/draco_decoder.js',
'assets/terminal/models.js?v=20261030b',
'assets/terminal/terminal-3d.js?v=20261030f',
'assets/terminal/camera-card.js'
];

function boot() {
if (!window.Legend) return;
var L = window.Legend;
var root = document.getElementById('terminal');
if (!root) return;

L.reveal(root);

var scene = root.querySelector('.s6-scene');
var stage = root.querySelector('.s6-stage');
var canvas = root.querySelector('.s6-canvas');
var flash = root.querySelector('.s6-flash');
var labels = [
root.querySelector('.s6-label--1'),
root.querySelector('.s6-label--2'),
root.querySelector('.s6-label--3')
];
var acts = Array.prototype.slice.call(root.querySelectorAll('.s6-act'));
var gsap = L.gsap || window.gsap;
var ST = L.ScrollTrigger || window.ScrollTrigger;
var isMobile = L.isMobile ? L.isMobile() : window.matchMedia('(max-width: 768px)').matches;
var canRender = !!(window.WebGLRenderingContext);
var viewer = null;
var failed = false;
var depPromise = null;
var dockTarget = 0;
var spinTarget = 0;
var appearTarget = 0;
var removeTarget = 0;
var lastDock = 0;
var flashTimer = 0;
var screenLevel = 0;

/* 壁纸亮度直接跟 02→03 的滚动进度走：进度到 80% 就全亮，03 居中时不再补动画 */
function updateScreen(p) {
p = Math.max(0, Math.min(1, p));
var t = Math.max(0, Math.min(1, (p - 0.04) / 0.76));
t = t * t * (3 - 2 * t);   /* smoothstep：起手柔和，收尾干净 */
screenLevel = t;
if (viewer) viewer.setScreenLevel(t);
}

function setState(n) {
if (scene) scene.setAttribute('data-state', String(n));
if (scene) scene.classList.toggle('is-engaged', n >= 2);
for (var i = 0; i < labels.length; i++) {
if (!labels[i]) continue;
labels[i].classList.toggle('is-on', i === n - 1);
}
}

function fireFlash() {
if (!flash) return;
flash.classList.add('is-on');
if (flashTimer) window.clearTimeout(flashTimer);
flashTimer = window.setTimeout(function () { flash.classList.remove('is-on'); }, 420);
}

function applyTargets(snap) {
dockTarget = Math.max(0, Math.min(1, dockTarget));
spinTarget = Math.max(0, Math.min(90, spinTarget));
appearTarget = Math.max(0, Math.min(1, appearTarget));
removeTarget = Math.max(0, Math.min(1, removeTarget));
if (!viewer) return;
viewer.setTarget(dockTarget, spinTarget, appearTarget, removeTarget);
if (snap) {
viewer.current.dock = viewer.target.dock;
viewer.current.spin = viewer.target.spin;
viewer.current.appear = viewer.target.appear;
viewer.current.remove = viewer.target.remove;
viewer.render();
}
if (scene) scene.classList.toggle('is-engaged', dockTarget > .985);
if (dockTarget >= .985 && lastDock < .985) fireFlash();
lastDock = dockTarget;
}

function loadScript(src) {
return new Promise(function (resolve, reject) {
var s = document.createElement('script');
s.src = src;
s.async = false;
s.onload = function () { resolve(); };
s.onerror = function () { reject(new Error('failed to load ' + src)); };
document.head.appendChild(s);
});
}

function ensureDeps() {
if (window.S6Terminal3D && window.S6_MODELS) return Promise.resolve();
if (!depPromise) {
depPromise = DEPS.reduce(function (p, src) {
return p.then(function () { return loadScript(src); });
}, Promise.resolve());
}
return depPromise;
}

function startViewer() {
if (viewer || failed) return;
ensureDeps().then(function () {
if (viewer || failed) return;
var v = new window.S6Terminal3D(canvas, { reduceMotion: L.reduceMotion });
return v.load(window.S6_MODELS).then(function () {
viewer = v;
v.setScreenLevel(screenLevel);
applyTargets(true);
if (scene) scene.classList.add('is-live');
v.start();
observeVisibility();
});
})['catch'](function (err) {
failed = true;
if (window.console && console.warn) console.warn('[S6] 3D 不可用，使用静态海报', err);
});
}

function observeVisibility() {
if (!viewer || !window.IntersectionObserver) return;
var io = new IntersectionObserver(function (entries) {
var e = entries[0];
if (!e) return;
if (e.isIntersecting) viewer.start();
else viewer.stop();
}, { rootMargin: '200px 0px' });
io.observe(scene);

}

/* 子模块卡组：摄像头卡片的实时 3D（滚到附近再加载，失败则保留海报） */
var deck = root.querySelector('.s6-deck');
var deckCard = root.querySelector('.s6-card--main');
var deckCanvas = root.querySelector('.s6-card-canvas');
var camViewer = null;
var camLoading = false;

function startCamCard() {
if (camViewer || camLoading) return;
if (isMobile || L.reduceMotion || !canRender) return;
camLoading = true;
ensureDeps().then(function () {
if (!window.S6CameraCard || !window.S6_MODELS || !window.S6_MODELS.subcamera) return;
var v = new window.S6CameraCard(deckCanvas, { reduceMotion: L.reduceMotion });
return v.load(window.S6_MODELS.subcamera).then(function () {
camViewer = v;
if (deckCard) deckCard.classList.add('is-live');
v.start();
if (window.IntersectionObserver && deckCard) {
var io = new IntersectionObserver(function (entries) {
v.visible = !!(entries[0] && entries[0].isIntersecting);
}, { rootMargin: '140px 0px' });
io.observe(deckCard);
}
});
})['catch'](function (err) { if (window.console) console.warn('[S6] 子模块卡片 3D 未加载', err); });
}

if (deck) {
if (window.IntersectionObserver) {
var deckIO = new IntersectionObserver(function (entries) {
if (entries[0] && entries[0].isIntersecting) {
deckIO.disconnect();
startCamCard();
}
}, { rootMargin: '280px 0px' });
deckIO.observe(deck);
} else {
window.setTimeout(startCamCard, 1500);
}
}

/* 每个叙事段进入视口时点亮进度点，并同步场景状态（移动端由滚动接管统一控制） */
if (!isMobile) acts.forEach(function (act, idx) {
if (!ST) return;
ST.create({
trigger: act,
start: 'top 55%',
end: 'bottom 45%',
onToggle: function (self) {
act.classList.toggle('is-on', self.isActive);
if (self.isActive) setState(idx + 1);
}
});
});

/* ---------- 三段卡位：滚轮一格 = 播放到下一段居中位置并停住 ---------- */
/* 竖屏 / 近方屏（与 CSS 堆叠分支同条件）：三段文案已经常显并排布，
   再劫持滚轮去"卡位"会让每一段都跳一下，这里直接不做。 */
var stackedPortrait = false;
try { stackedPortrait = window.matchMedia('(min-width:769px) and (max-aspect-ratio:11/10)').matches; } catch (e) {}
if (!isMobile && !stackedPortrait && !L.reduceMotion) (function () {
var raf = 0;
var tweening = false;
var cooldown = 0;
var stepCache = null;   // 三段卡位的文档坐标缓存

function docTop(el) {
var t = 0;
while (el) {
t += el.offsetTop;
el = el.offsetParent;
}
return t;
}

function stepPoints() {
if (stepCache) return stepCache;
var vh = window.innerHeight;
var list = [];
for (var i = 0; i < acts.length; i++) {
list.push(docTop(acts[i]) + acts[i].offsetHeight / 2 - vh / 2);
}
stepCache = list;
return list;
}

/* 旧实现每个 wheel 事件都跑一遍 stepPoints()，内部沿 offsetParent 链读
   offsetTop / offsetHeight —— 滚动中等于持续触发同步布局（layout thrashing）。
   这里只在布局真的可能变化时失效重算。 */
function invalidateSteps() { stepCache = null; }
window.addEventListener('resize', invalidateSteps, { passive: true });
window.addEventListener('orientationchange', invalidateSteps, { passive: true });
window.addEventListener('load', invalidateSteps, { once: true });
document.addEventListener('load', invalidateSteps, true);   // 懒加载图片撑高页面
if (ST && ST.addEventListener) ST.addEventListener('refresh', invalidateSteps);
if (document.fonts && document.fonts.ready) document.fonts.ready.then(invalidateSteps);

function playTo(target) {
var from = window.pageYOffset;
var to = Math.max(0, target);
var t0 = window.performance ? performance.now() : Date.now();
var dur = 760;
tweening = true;
function tick(now) {
var t = Math.min(1, (now - t0) / dur);
var e = t < .5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
window.scrollTo(0, from + (to - from) * e);
if (t < 1) {
raf = window.requestAnimationFrame(tick);
} else {
raf = 0;
tweening = false;
cooldown = (window.performance ? performance.now() : Date.now()) + 420;
}
}
raf = window.requestAnimationFrame(tick);
}

window.addEventListener('wheel', function (e) {
if (!e.deltaY) return;
var list = stepPoints();
var vh = window.innerHeight;
var y = window.pageYOffset;
if (y < list[0] - vh * 0.55 || y > list[list.length - 1] + vh * 0.55) return;
if (tweening || (window.performance ? performance.now() : Date.now()) < cooldown) {
e.preventDefault();
return;
}
var dir = e.deltaY > 0 ? 1 : -1;
var target = null;
var i;
if (dir > 0) {
for (i = 0; i < list.length; i++) {
if (list[i] > y + 8) { target = list[i]; break; }
}
} else {
for (i = list.length - 1; i >= 0; i--) {
if (list[i] < y - 8) { target = list[i]; break; }
}
}
if (target === null) return;
e.preventDefault();
playTo(target);
}, { passive: false });
})();
if (!gsap || !ST || L.reduceMotion) {
if (scene) scene.classList.remove('is-live');
return;
}

/* 移动端：本屏钉住，滚动只推进 01/02/03 文案与机身状态 */
if (isMobile) {
setupMobileStory();
scheduleLoad();
return;
}

if (!canRender) {
if (scene) scene.classList.remove('is-live');
return;
}

/* 移动端滚动叙事：钉住舞台，三段进度驱动模型 */
function setupMobileStory() {
var current = -1;
var storyStep = 0, storyPinned = false;
var pinStart = 0, pinLen = 1, touchY = 0, touchOn = false, touchGuard = false, lastWheel = 0;
var stepPos = [0, 0.22, 0.52];

function applyStep() {
var idx = storyStep;
dockTarget = 1;
spinTarget = idx >= 1 ? 90 : 0;
removeTarget = idx >= 2 ? 1 : 0;
updateScreen(idx >= 2 ? 1 : 0);
appearTarget = 1;
applyTargets();
if (idx !== current) {
current = idx;
for (var k = 0; k < acts.length; k++) acts[k].classList.toggle('is-on', k === idx);
setState(idx + 1);
}
}
applyStep();

var tweenId = 0;
function tweenScroll(to, dur, done) {
/* 每条补间带一个 token：新手势进来时立刻作废上一条，避免两条滚动互相拉扯 */
var id = ++tweenId;
var from = window.pageYOffset;
var t0 = (window.performance ? performance.now() : Date.now());
function tick(now) {
if (id !== tweenId) return;
var t = Math.min(1, (now - t0) / dur);
var e = t < .5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
window.scrollTo(0, from + (to - from) * e);
if (t < 1) window.requestAnimationFrame(tick);
else if (done) done();
}
window.requestAnimationFrame(tick);
}

/* 一次手势 = 一步：上一条补间还没跑完也要接收这次手势（不再因为「动画中」吞掉滑动） */
function goStep(dir) {
if (!storyPinned) return;
var next = storyStep + dir;
if (next < 0) {
tweenScroll(pinStart - window.innerHeight * 0.35, 520);
return;
}
if (next > 2) {
tweenScroll(pinStart + pinLen + window.innerHeight * 0.35, 520);
return;
}
storyStep = next;
applyStep();
tweenScroll(pinStart + pinLen * stepPos[storyStep], 620);
}

function setPinned(on) {
storyPinned = on;
if (stage) stage.classList.toggle('is-pinned', on);
}
window.addEventListener('touchstart', function (e) {
if (!e.touches || !e.touches[0] || !stage) return;
touchY = e.touches[0].clientY;
/* 记录手势起点是否已在钉屏范围内：在钉屏前一点点开始的滑动——
   它可能把页面滑进钉屏后才结束——也要算作「一次手势 = 一步」，
   否则用户会觉得滑了没反应，要多滑两三次 */
var top = stage.getBoundingClientRect().top;
touchGuard = storyPinned || (top > -1 && top < window.innerHeight * 0.15);
touchOn = true;
}, { passive: true });
window.addEventListener('touchmove', function (e) {
if (!storyPinned) return;
if (e.cancelable) e.preventDefault();
}, { passive: false });
window.addEventListener('touchend', function (e) {
if (!touchOn) return;
touchOn = false;
var t = e.changedTouches && e.changedTouches[0];
if (!t) return;
var dy = t.clientY - touchY;
if (Math.abs(dy) < 28) return;
if (!storyPinned || !touchGuard) return;   // 还没进入钉屏 / 从很远处滑进来：只负责进入本段
goStep(dy < 0 ? 1 : -1);
});
window.addEventListener('touchcancel', function () { touchOn = false; });
window.addEventListener('wheel', function (e) {
if (!storyPinned || !e.deltaY) return;
e.preventDefault();
var now = (window.performance ? performance.now() : Date.now());
if (now - lastWheel < 220) return;
lastWheel = now;
goStep(e.deltaY > 0 ? 1 : -1);
}, { passive: false });

var mainST = ST.create({
trigger: stage,
start: 'top top',
end: '+=150%',
pin: true,
pinSpacing: true,
anticipatePin: 1,
invalidateOnRefresh: true,
onRefresh: function (self) {
pinStart = self.start;
pinLen = self.end - self.start;
},
onEnter: function () {
/* 进入钉屏时不再回拉页面：旧逻辑会把已经滑进来的页面拽回钉屏起点，
   观感就是「页面上移一下又立刻归位」，同时还会让随后的第一次滑动失效 */
setPinned(true); storyStep = 0; applyStep();
},
onEnterBack: function () { setPinned(true); storyStep = 2; applyStep(); },
onLeave: function () { setPinned(false); storyStep = 2; applyStep(); },
onLeaveBack: function () { setPinned(false); storyStep = 0; applyStep(); }
});
pinStart = mainST.start;
pinLen = mainST.end - mainST.start;
/* 页面懒加载图片/字体可能改变上方高度，重算一次钉屏起点，避免触发位置漂移 */
function refreshStory() { if (ST) ST.refresh(); }
window.addEventListener('load', refreshStory, { once: true });
if (document.fonts && document.fonts.ready) document.fonts.ready.then(refreshStory);
window.setTimeout(refreshStory, 1500);
}

/* 刚进入本段 → 第一段文字居中：手机渐入 + 下落贴合 */
ST.create({
trigger: stage,
start: 'top 88%',
endTrigger: acts[0],
end: 'center 50%',
onUpdate: function (self) {
dockTarget = self.progress;
appearTarget = Math.min(1, Math.max(0, (self.progress - 0.12) / 0.36));
applyTargets();
},
onLeave: function () { dockTarget = 1; appearTarget = 1; applyTargets(); },
onLeaveBack: function () { dockTarget = 0; appearTarget = 0; applyTargets(); }
});

/* 第一段 → 第二段文字居中：以万象环圆心为中心逆时针旋转 90° */
ST.create({
trigger: acts[0],
start: 'center 50%',
endTrigger: acts[1],
end: 'center 50%',
onUpdate: function (self) { spinTarget = Math.min(1, self.progress / 0.9) * 90; applyTargets(); },
onLeave: function () { spinTarget = 90; applyTargets(); },
onLeaveBack: function () { spinTarget = 0; applyTargets(); }
});

/* 第二段 → 第三段文字居中：手机直接移走 */
ST.create({
trigger: acts[1],
start: 'center 50%',
endTrigger: acts[2],
end: 'center 50%',
onUpdate: function (self) { removeTarget = self.progress; applyTargets(); updateScreen(self.progress); },
onLeave: function () { removeTarget = 1; applyTargets(); updateScreen(1); },
onLeaveBack: function () { removeTarget = 0; applyTargets(); updateScreen(0); }
});

/* 进入本段之前就把模型准备好：首屏渲染完成后空闲时加载，避免滚动到此处才闪一下 */
function scheduleLoad() {
window.setTimeout(startViewer, 150);
}
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', scheduleLoad, { once: true });
else scheduleLoad();
}

if (window.Legend) {
boot();
} else {
document.addEventListener('DOMContentLoaded', boot);
}
})();


/* 子模块卡片：五张卡的介绍区等高（主卡文案最长），标题与图片区对齐 */
(function () {
'use strict';
var deckEl = null;
var timer = 0;
function syncFutureCards() {
if (!deckEl || !document.documentElement.contains(deckEl)) deckEl = document.querySelector('.s6-deck');
if (!deckEl) return;
var caps = Array.prototype.slice.call(deckEl.querySelectorAll('.s6-card figcaption'));
if (!caps.length) return;
for (var i = 0; i < caps.length; i++) caps[i].style.minHeight = '';
if (!window.matchMedia || !window.matchMedia('(min-width: 769px)').matches) return;
var max = 0;
for (var j = 0; j < caps.length; j++) {
var h = caps[j].getBoundingClientRect().height;
if (h > max) max = h;
}
for (var k = 0; k < caps.length; k++) caps[k].style.minHeight = max + 'px';
}
function later() { window.setTimeout(syncFutureCards, 60); }
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', later);
else later();
window.addEventListener('load', syncFutureCards, { once: true });
if (document.fonts && document.fonts.ready) document.fonts.ready.then(syncFutureCards);
window.addEventListener('resize', function () { window.clearTimeout(timer); timer = window.setTimeout(syncFutureCards, 160); });
})();
